var num=100;
var theta;

function setup() {
  createCanvas(500, 500);
  background(0);
  stroke(255,50);
  strokeWeight(2);
  fill(255, 50);
}

function draw() {
  background(0);
  translate(width/2, height/2);
  for (let i=0; i<num; i++) {
    push();
    let offSet = TWO_PI/num*i;
    rotate(offSet);
    let x1 = map(sin(theta+offSet*5),-1,1,0,80);
    let x2 = x1 -50 ;
    let x3 = 100;
    let x4 = x3 + 100;
    bezier(x1, 0, 100, -100, x3, 50, x4, -100);
    pop();
  }
  theta -= 0.0523;
}
